import React, { useState, useEffect } from 'react'
import SlideBarComponent from '../../components/SlideBar/SlideBarComponent'
import { PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { getTotalIncomeByGender } from '../../service/statisticsservice'
import './IncomeGender.scss'
import VacationDayGender from '../VacationDayGender/VacationDayGender';

const COLORS = {
    'Nam': '#4caf50',  // Xanh lá
    'Nữ': '#f44336' // Đỏ
};

const data = [
    { name: 'Nam', value: 20 },
    { name: 'Nữ', value: 15 },
];

const IncomeGender = () => {

    const VacationDayGender = () => {
        return (
            <div className='container d-flex'>
                <div className='sidebar'>
                    <SlideBarComponent />
                </div>

                <div className='content p-4 w-100'>
                    <h3 className="mb-4">Thống kê Ngày Nghỉ - Giới tính</h3>

                    <div className="row">
                        <div className="col-md-6">
                            <table className="table table-bordered table-hover">
                                <thead className="table-dark">
                                    <tr>
                                        <th>Giới tính</th>
                                        <th>Số ngày nghỉ</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {data.map((item, index) => (
                                        <tr key={index}>
                                            <td>{item.name}</td>
                                            <td>{item.value} ngày</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>

                        <div className="col-md-6">
                            <h5 className="text-center mb-4" style={{ paddingBottom: '20px' }}>Biểu đồ Ngày Nghỉ</h5>
                            <ResponsiveContainer width="100%" height={400}>
                                <PieChart>
                                    <Pie
                                        data={data}
                                        dataKey="value"
                                        nameKey="name"
                                        cx="50%"
                                        cy="50%"
                                        outerRadius={150}
                                        fill="#8884d8"
                                        label
                                    >
                                        {data.map((entry, index) => (
                                            <Cell key={`cell-${index}`} fill={['#007bff', '#28a745'][entry.name]} />
                                        ))}
                                    </Pie>
                                    <Tooltip
                                        formatter={(value) => [`${value} ngày`, 'Số ngày nghỉ']}
                                        labelFormatter={(label) => `Giới tính: ${label}`}
                                    />
                                    <Legend />
                                </PieChart>
                            </ResponsiveContainer>
                        </div>
                    </div>
                </div>
            </div>
        );
    };
}

export default VacationDayGender
